BeginPlay()
{
    ShowUI("Start HUD");
    StartSiege(MorninghollowSiege);

    CreateAgent(Day)
        .Team(Morninghollow.Day)
        .Bot(DefaultBot)
        .Resources(StartingResources)
        .Income(5)
        .UnitCap(20)
        .KillReward(5);

    CreateAgent(Night)
        .Team(Morninghollow.Night)
        .Bot(DefaultBot)
        .Resources(StartingResources)
        .Income(5)
        .UnitCap(20)
        .KillReward(5);

}
